/**
 * Order number (Q-025, DECISIONS A-053 ②, DATABASE.md §19.15).
 *
 * `NZ-YYYYMM-NNNNNN`: KST month of the DB instant + one global PostgreSQL sequence (never reset, at least 6 digits,
 * more when needed). The number is generated by the database function `next_order_number()` so that the month and the
 * counter come from the database, never from the application clock.
 *
 * Call it with the SAME transaction executor that inserts the order (inside `runBookingTx`): it starts no transaction
 * of its own. The default instant is `now()` = the transaction start, which is also the order's `created_at` default, so
 * the number's month is the KST month of the order's creation. If the transaction rolls back, the number is simply
 * never used (sequences are not transactional): gaps are allowed and the number is never reissued.
 *
 * An order number identifies an order for people (support, receipts). It is NOT a secret and grants no access: order
 * lookups always require the owner's session / access session (TEST ORD-11).
 */
import type { SqlExecutor } from "../db/sql";

/** Same rule as the CHECK `orders_order_number_format_ck`. */
export const ORDER_NUMBER_PATTERN = /^NZ-[0-9]{6}-[0-9]{6,}$/;

export function isOrderNumber(value: unknown): value is string {
  return typeof value === "string" && value.length <= 40 && ORDER_NUMBER_PATTERN.test(value);
}

/**
 * Issues the next order number in the caller's transaction. The format is re-checked here as a defence in depth: a
 * value the CHECK would refuse is reported before it reaches the INSERT.
 */
export async function nextOrderNumber(tx: SqlExecutor): Promise<string> {
  const rows = await tx<{ order_number: string }>(`SELECT next_order_number() AS "order_number"`, []);
  const value = rows[0]?.order_number;
  if (!isOrderNumber(value)) throw new Error("next_order_number() returned an unexpected value");
  return value;
}
